changeSet.sql:
CREATE TABLE points_catalog (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(200) NOT NULL CHECK (length(trim(name)) > 0), discipline_type VARCHAR(32) NOT NULL CHECK (discipline_type IN ('SPRINT','PARALLEL_SPRINT','SLALOM','LONG_RACE')), version BIGINT NOT NULL DEFAULT 0, preset BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE points_catalog_rows (table_id BIGINT NOT NULL REFERENCES points_catalog(id) ON DELETE CASCADE, place INTEGER NOT NULL CHECK (place > 0), points INTEGER NOT NULL CHECK (points >= 0), PRIMARY KEY (table_id, place));
INSERT INTO points_catalog(name, discipline_type) VALUES ('Российская таблица очков - Спринт', 'SPRINT'), ('Российская таблица очков - Параллельный спринт', 'PARALLEL_SPRINT'), ('Российская таблица очков - Слалом', 'SLALOM'), ('Российская таблица очков - Длинная гонка', 'LONG_RACE');
UPDATE points_catalog SET preset = true;
INSERT INTO points_catalog_rows(table_id, place, points) SELECT t.id, p, (105 - 5 * p) * CASE t.discipline_type WHEN 'SPRINT' THEN 1 WHEN 'PARALLEL_SPRINT' THEN 2 WHEN 'SLALOM' THEN 3 ELSE 4 END FROM points_catalog t CROSS JOIN generate_series(1, 20) p;
